package com.abemu.coaster.sim

import kotlin.math.PI
import kotlin.math.hypot
import kotlin.math.sin
import kotlin.math.sqrt
import kotlin.random.Random

/**
 * Parameters for one coaster. The track itself is generated by [CoasterLibrary.build], which keeps
 * every hill within the energy available (with margin) so the ride is always completable.
 *
 * @param height lift crest height (LIFT) or top-hat height (LAUNCH), metres.
 * @param hills1 hill heights before the MCBR, as fractions (0..1) of the height the train could reach.
 * @param mcbrFrac MCBR height as a fraction of the reachable height.
 * @param hills2 hill heights between the MCBR and the final brakes (fractions).
 * @param layout plan-view template index; [seed] varies the curves.
 */
data class CoasterSpec(
    val id: String,
    val name: String,
    val type: ProfileType,
    val height: Double,
    val launchSpeed: Double = 0.0,
    val liftSpeed: Double = 3.5,
    val hills1: List<Double>,
    val mcbrFrac: Double,
    val hills2: List<Double>,
    val cars: Int,
    val ridersPerCar: Int,
    val layout: Int,
    val seed: Int,
    val park: String? = null,
    val note: String = "",
    val hasMcbr: Boolean = true,
    val unloadStation: Boolean = false,
    /** A dispatch is held in the station until the lift is clear and the train on the course is stopped on its brakes (Millennium Force). */
    val dispatchHoldForCourse: Boolean = false,
    /** If > 0, the MCBR is a tunnel block whose exit LSM launches trains to this speed (m/s). */
    val tunnelLaunch: Double = 0.0,
    /**
     * Swing launch (Top Thrill 2): forward LSM launch to [swing].first m/s that falls back off the top hat,
     * a backward launch to [swing].second m/s up the rear spike, then the final forward launch to [launchSpeed].
     */
    val swing: Pair<Double, Double>? = null,
    /** Height of the rear vertical spike for a swing launch, metres. */
    val spikeHeight: Double = 0.0,
    /** LAUNCH ride whose "launch" is an LSM-driven incline lift (Maverick): [launchSpeed] is the climb speed. */
    val lsmLift: Boolean = false,
    /**
     * Moving-block station: a train may follow the train ahead into a station zone (unload / load) as soon as that
     * train is released and moving, instead of waiting for it to clear the block. Station moves happen together.
     */
    val movingBlockStation: Boolean = false,
    /**
     * Paired (dual-load) station: a rear loading position behind the main one, plus holding blocks behind the station.
     * Two trains load at once and leave as a pair; the rear one follows the front train to the foot of the lift.
     */
    val pairedStation: Boolean = false,
    /** Real hill heights before the MCBR in metres (replaces [hills1]); each is still capped by the energy available. */
    val hillsM: List<Double>? = null,
    /** Height the first drop bottoms out at, metres. */
    val dropTo: Double = 3.0,
    /** Gentle downhill run (m) from the station to where the lift chain picks the train up. */
    val preLift: Double = 0.0,
    /** Trim brakes after hill [trimAfter] of the course before the MCBR, capping the train at [trimSpeed] (m/s). */
    val trimAfter: Int = -1,
    val trimSpeed: Double = 0.0,
    /** Station track height above grade, metres. */
    val stationH: Double = 2.0,
    /** Valley height between the hills before the MCBR (ground-level tunnels sit low). */
    val valleyH: Double = 4.0,
    /** Height of the trim brakes and the turnaround after them. */
    val turnH: Double = 4.0,
    /** Top speed at the bottom of the first drop (m/s), held there by wheel scrub in the pull-out; 0 = none. */
    val dropSpeed: Double = 0.0,
    /** Fixed MCBR height (metres), instead of one sized from the energy left. */
    val mcbrHeight: Double = 0.0,
    /** Speed a course brake run lets a train through at when the block ahead is clear (m/s). */
    val passSpeed: Double = 6.0,
    /** Published track length (metres). OSM traces are flat, so they miss the length the hills add. */
    val trackLength: Double = 0.0,
)

object CoasterLibrary {
    private const val LOSS = 0.04 // conservative energy-head loss per metre (friction + drag)
    private const val LSM_ACCEL = 11.0

